[
 {"name":"Gran Hotel La Perla","aliases":"Gran Hotel La Perla|Hotel La Perla Pamplona","city":"pamplona","description":"A Belle Époque grand hotel facing Plaza del Castillo, where Hemingway history, balcony views and deeply traditional service place guests directly inside Pamplona's civic theatre.","vibe":"historic five-star intimacy on the city's main square","tags":"luxury,cultural,cozy","hours":"Reception operates 24 hours; breakfast, restaurant and valet arrangements vary.","link":"https://www.granhotellaperla.com/","location":"Plaza del Castillo 1, 31001 Pamplona, Spain","lat":42.81655,"lng":-1.64286,"arrival":"Old-town traffic controls and festival barriers affect vehicle access; arrange valet, adapted access and San Fermín arrival directly.","best":"Best for queer couples wanting landmark history and instant access to Harrotu, Pride squares and the old town.","crowd":"LGBTQ+ couples mix with heritage, luxury, literary and festival guests.","dress":"Polished city casual.","inclusion":"Selected through current specialist LGBTQ-welcoming accommodation evidence paired with an active official hotel source; no queer ownership claim.","basis":"Current specialist inclusion signal plus first-party property information.","class":"Five-star independent historic hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.granhotellaperla.com/","https://www.expedia.com/Pamplona-Hotels-LGBTQ-Welcoming-Hotel.0-0-d2829-tLGBTQWelcomingHotel.Travel-Guide-Filter-Hotels"]},
