 {"name":"Old Bank Hotel","aliases":"Old Bank Hotel|Old Bank Oxford","city":"oxford","description":"A privately owned High Street hotel that turns former banking rooms into art-filled bedrooms, with Quod's terrace and university spires almost pressed against the windows.","vibe":"art-rich independent luxury in the academic heart","tags":"luxury,cultural,cozy","hours":"Reception operates 24 hours; Quod restaurant, room service and parking arrangements vary.","link":"https://www.oldbankhotel.co.uk/","location":"91-94 High Street, Oxford OX1 4BJ, United Kingdom","lat":51.75220,"lng":-1.25183,"arrival":"High Street restrictions require the hotel's arrival directions; reserve parking and confirm lift or adapted-room access.","best":"Best for queer couples seeking intimate service, contemporary art and maximum historic-centre atmosphere.","crowd":"LGBTQ+ couples mix with academics, cultural travellers, diners and international luxury guests.","dress":"Elegant but unstuffy city wear.","inclusion":"Selected through current specialist LGBTQ-welcoming Oxford accommodation evidence and an active direct source; no ownership claim.","basis":"Current specialist inclusion signal paired with first-party property information.","class":"Five-star independent boutique hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.oldbankhotel.co.uk/","https://www.expedia.com/Oxford-Hotels-LGBTQ-Welcoming-Hotel.0-0-d9272-tLGBTQWelcomingHotel.Travel-Guide-Filter-Hotels"]},

 {"name":"Hotel Norge by Scandic","aliases":"Hotel Norge by Scandic|Hotel Norge Bergen","city":"bergen","description":"A glossy Bergen institution on Ole Bulls plass, with bold art, lively bars and a spa that turns the rainiest Pride afternoon into part of the itinerary.","vibe":"fashionable grand hotel with a highly social city pulse","tags":"luxury,social,cultural","hours":"Reception operates 24 hours; spa, pool, restaurants, bars and breakfast vary.","link":"https://www.scandichotels.com/hotels/norway/bergen/hotel-norge-by-scandic","location":"Nedre Ole Bulls plass 4, 5012 Bergen, Norway","lat":60.39200,"lng":5.32411,"arrival":"The central square can be busy during festivals; confirm parking, pool access and an adapted or quiet room.","best":"Best for queer friends and couples wanting a glamorous lobby within a short walk of Fincken.","crowd":"LGBTQ+ Pride guests mix with musicians, conference, luxury leisure and local diners.","dress":"Nordic fashion casual; sharper for evening bars.","inclusion":"Scandic publishes explicit diversity and inclusion commitments, including equal treatment across sexual orientation and gender identity.","basis":"Active first-party property details plus current corporate inclusion policy.","class":"Five-star Scandic landmark hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.scandichotels.com/hotels/norway/bergen/hotel-norge-by-scandic","https://www.scandichotelsgroup.com/sustainability/diversity-and-inclusion/"]},
 {"name":"Bergen Børs Hotel","aliases":"Bergen Børs Hotel|Bergen Bors Hotel","city":"bergen","description":"The former stock exchange has become a sculptural design hotel where monumental columns, contemporary rooms and award-winning dining face directly into Bergen's historic commercial core.","vibe":"monumental heritage design with serious culinary ambition","tags":"luxury,cultural,cozy","hours":"Reception operates 24 hours; restaurants, bar, gym and breakfast follow separate schedules.","link":"https://www.bergenbors.no/en/","location":"Vågsallmenningen 1, 5014 Bergen, Norway","lat":60.39456,"lng":5.32630,"arrival":"Historic interiors create varied room shapes; confirm step-free access, bedding and nearby garage arrangements.","best":"Best for queer couples wanting design, dining and a rain-minimising central location.","crowd":"LGBTQ+ couples mix with food travellers, business guests and heritage-focused city breakers.","dress":"Refined Nordic casual.","inclusion":"De Bergenske communicates equal-opportunity and people-focused sustainability commitments; no queer ownership or dedicated programme is claimed.","basis":"Current first-party hotel source and group responsibility framework.","class":"Five-star historic design hotel","coords":"Exact official address checked 2026-08-28.","sources":["https://www.bergenbors.no/en/","https://www.debergenske.no/en/about-us/sustainability"]},
